'use strict';
(()=>{const KEY='gp-nutrition-v2-ergonomic-prototype-only', $=id=>document.getElementById(id), today=()=>{const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')},fmt=(n,d=1)=>Number(n).toLocaleString('fr-FR',{maximumFractionDigits:d}),safe=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;','\'':'&#39;'}[c]));
const KINDS=[['waist','Taille'],['hips','Hanches'],['glutes','Fessiers'],['thigh','Cuisse'],['chest','Poitrine'],['upperThigh','Haut de cuisse'],['arm','Bras']];
const DEMO=new URLSearchParams(location.search).get('demo')==='1';
const demoDates=Array.from({length:9},(_,i)=>{const d=new Date();d.setHours(12,0,0,0);d.setDate(d.getDate()-28+i*3.5);return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')});
const demoWeights=[74.5,74.2,74.1,73.8,73.6,73.4,73.2,73.1,72.8];
const demoWaist=[85,84.7,84.3,84,83.5,83.2,82.8,82.4,82];
const demoGlutes=[108,108.1,108.3,108.5,108.6,108.8,109,109.1,109.3];
const demoData={weights:Object.fromEntries(demoDates.map((d,i)=>[d,demoWeights[i]])),measurements:Object.fromEntries(demoDates.map((d,i)=>[d,{waist:demoWaist[i],hips:101-i*.2,glutes:demoGlutes[i],thigh:56+i*.08,chest:97,upperThigh:65,arm:29+i*.04}]))};
const read=()=>{try{const real=JSON.parse(localStorage.getItem(KEY))||{};return DEMO?{...real,weights:demoData.weights,measurements:demoData.measurements}:real}catch{return DEMO?demoData:{}}},write=db=>{if(DEMO)return;localStorage.setItem(KEY,JSON.stringify(db));};
if(DEMO){const banner=document.createElement('div');banner.className='tracking-demo-banner';banner.innerHTML='<strong>🧪 Démonstration : données fictives</strong><span>9 relevés de poids et de mensurations sur 30 jours. Tes données réelles ne sont pas modifiées.</span><a href="'+location.pathname+'#suivi">Quitter la démonstration</a>';document.getElementById('tracking-dashboard').prepend(banner);document.querySelectorAll('[data-quick], [data-delete-weight], [data-delete-measure]').forEach(b=>b.disabled=true);}

const dayOffset=(date,n)=>{const d=new Date(date+'T12:00:00');d.setDate(d.getDate()+n);return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')};
const avg=values=>values.length?values.reduce((a,b)=>a+b,0)/values.length:null;
const stat=(label,value)=>'<div class="track-stat"><b>'+value+'</b><small>'+label+'</small></div>';
const diff=(a,b,unit)=>a==null||b==null?'—':(b-a>0?'+':'')+fmt(b-a)+' '+unit;
const chartSelections={};
function chart(target,title,entries,unit,range,color='#5de1c1'){
 const el=$(target),end=range?.end||today(),start=range?.start||dayOffset(end,-29);
 if(!range?.valid||!entries.length){el.innerHTML='<div class="track-chart"><h3>'+safe(title)+'</h3><p class="chart-note">Aucun relevé pour cette période. Les journées sans saisie ne sont pas comptées.</p></div>';return;}
 const days=Math.max(1,Math.round((new Date(end+'T12:00:00')-new Date(start+'T12:00:00'))/86400000)+1);
 const byDate=new Map(entries.map(e=>[e.date,e]));
 const selected=byDate.has(chartSelections[target])?chartSelections[target]:entries.at(-1).date;
 chartSelections[target]=selected;
 const active=byDate.get(selected),values=entries.map(e=>e.value),min=Math.min(...values),max=Math.max(...values),spread=Math.max(max-min,.5),low=min-spread*.18,high=max+spread*.18;
 const w=330,h=190,left=42,right=14,top=14,bottom=39;
 const x=date=>left+(w-left-right)*(new Date(date+'T12:00:00')-new Date(start+'T12:00:00'))/Math.max(1,(days-1)*86400000);
 const y=value=>top+(h-top-bottom)*(high-value)/(high-low);
 const points=entries.map(e=>'<circle cx="'+x(e.date)+'" cy="'+y(e.value)+'" r="'+(e.date===selected?5.5:4)+'" fill="'+(e.date===selected?'#ffca7c':color)+'" stroke="#371536" stroke-width="1.5"><title>'+displayDate(e.date)+' : '+fmt(e.value)+' '+unit+'</title></circle>').join('');
 // Relier finement les relevés existants, sans créer de valeur pour les dates sans saisie.
 const lines=entries.length>1?'<polyline fill="none" stroke="'+color+'" stroke-opacity=".9" stroke-width="1.35" stroke-linecap="round" stroke-linejoin="round" points="'+entries.map(e=>x(e.date)+','+y(e.value)).join(' ')+'"/>':'';
 const ticks=Array.from(new Set([0,Math.floor((days-1)/2),days-1])).map(i=>{const date=dayOffset(start,i);return '<text x="'+x(date)+'" y="181" text-anchor="middle" font-size="11" fill="#f4d9b1">'+displayDate(date).slice(0,5)+'</text>';}).join('');
 const grid=[0,.5,1].map(t=>{const v=low+(high-low)*t;return '<line x1="'+left+'" y1="'+y(v)+'" x2="'+(w-right)+'" y2="'+y(v)+'" stroke="#ad8caa" stroke-opacity=".3" stroke-dasharray="3 4"/><text x="1" y="'+(y(v)+3)+'" font-size="10" fill="#f4d9b1">'+fmt(v)+'</text>';}).join('');
 const selector=entries.map(e=>'<button type="button" data-chart-target="'+target+'" data-chart-date="'+e.date+'" aria-pressed="'+(e.date===selected)+'">'+displayDate(e.date).slice(0,5)+'</button>').join('');
 el.innerHTML='<div class="track-chart"><h3>'+safe(title)+'</h3><svg viewBox="0 0 330 190" role="img" aria-label="'+safe(title)+' du '+displayDate(start)+' au '+displayDate(end)+'">'+grid+lines+'<line x1="'+x(selected)+'" x2="'+x(selected)+'" y1="'+top+'" y2="'+(h-bottom)+'" stroke="#ffca7c" stroke-dasharray="4 3"/>'+points+ticks+'</svg><div class="chart-selected" aria-live="polite"><span>Relevé du '+displayDate(selected)+'</span><strong>'+fmt(active.value)+' '+unit+'</strong>'+(active.detail?'<small>'+safe(active.detail)+'</small>':'')+'</div><p class="chart-note">'+entries.length+' relevé(s) · '+days+' jours affichés. Choisis une date enregistrée :</p><div class="chart-day-picker">'+selector+'</div></div>';
}
document.addEventListener('click',event=>{const b=event.target.closest('[data-chart-target][data-chart-date]');if(!b)return;chartSelections[b.dataset.chartTarget]=b.dataset.chartDate;const target=b.dataset.chartTarget;if(target==='weight-chart')renderWeight();else if(target==='measure-chart')renderMeasure();else if(target==='nutrition-chart')renderNutrition();else if(target.startsWith('analysis-chart-'))renderAnalysis();});
function period(id){const mode=$(id+"-window").value,custom=mode==="custom";$(id+"-custom").hidden=!custom;const end=custom?$(id+"-to").value:today(),start=custom?$(id+"-from").value:dayOffset(end,1-Number(mode));const valid=!!start&&!!end&&start<=end;$(id+"-period-error").hidden=valid;$(id+"-period-error").textContent="Choisis une date de début antérieure ou égale à la date de fin.";return {start,end,valid};}
function renderWeight(){const db=read(),list=Object.entries(db.weights||{}).filter(([date,v])=>/^\d{4}-\d{2}-\d{2}$/.test(date)&&Number.isFinite(Number(v))&&Number(v)>0).sort((a,b)=>a[0].localeCompare(b[0])).map(([date,v])=>({date,value:Number(v)})),range=period('weight'),visible=list.filter(e=>range.valid&&e.date>=range.start&&e.date<=range.end),last=visible.at(-1),previous=visible.at(-2);const latest=list.at(-1);$('weight-last').textContent=latest?fmt(latest.value)+' kg':'— kg';$('weight-last-date').textContent=latest?'Le '+displayDate(latest.date):'Aucune pesée';$('weight-average').textContent=visible.length?fmt(avg(visible.map(e=>e.value)))+' kg':'—';$('weight-difference').textContent=last&&previous?'Depuis la précédente : '+diff(previous.value,last.value,'kg'):visible.length+' pesée(s) sur la période';document.querySelectorAll('[data-weight-period]').forEach(b=>{const active=b.dataset.weightPeriod===$('weight-window').value;b.setAttribute('aria-pressed',String(active));});chart('weight-chart','Évolution du poids',visible,'kg',range);$('weight-history').innerHTML=visible.slice().reverse().map(e=>'<div class="track-entry"><span>'+e.date+' · '+fmt(e.value)+' kg</span><button data-delete-weight="'+e.date+'">Supprimer</button></div>').join('')||'<p class="tracking-note">Aucune pesée enregistrée.</p>';}
function renderMeasure(){const db=read(),kind=$('measure-kind').value,list=Object.entries(db.measurements||{}).filter(([date,record])=>record&&Number.isFinite(Number(record[kind]))&&Number(record[kind])>0).sort((a,b)=>a[0].localeCompare(b[0])).map(([date,record])=>({date,value:Number(record[kind])}));const range=period('measure'),visible=list.filter(e=>range.valid&&e.date>=range.start&&e.date<=range.end),latest=list.at(-1);$('measure-last').textContent=latest?fmt(latest.value)+' cm':'— cm';$('measure-last-date').textContent=latest?'Le '+displayDate(latest.date):'Aucune mesure pour cette zone';$('measure-average').textContent=visible.length?fmt(avg(visible.map(e=>e.value)))+' cm':'—';$('measure-difference').textContent=visible.length>1?'Évolution : '+diff(visible[0].value,visible.at(-1).value,'cm'):visible.length+' relevé(s) sur la période';document.querySelectorAll('[data-measure-period]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.measurePeriod===$('measure-window').value)));chart('measure-chart','Évolution : '+KINDS.find(x=>x[0]===kind)[1],visible,'cm',range);$('measure-history').innerHTML=visible.slice().reverse().map(e=>'<div class="track-entry"><span>'+displayDate(e.date)+' · '+fmt(e.value)+' cm</span><button data-delete-measure="'+e.date+'">Supprimer</button></div>').join('')||'<p class="tracking-note">Aucune mesure pour cette zone.</p>';}
function nutritionTotals(items){return(items||[]).reduce((a,i)=>{const q=Number(i.grams)/100;for(const k of ['kcal','p','c','f'])a[k]+=Number(i[k]||0)*q;return a},{kcal:0,p:0,c:0,f:0})}
function renderNutrition(){const db=read(),mode=$('nutrition-window').value,custom=mode==='custom';$('nutrition-custom').hidden=!custom;const end=custom?$('nutrition-to').value:today(),start=custom?$('nutrition-from').value:dayOffset(end,1-Number(mode));const valid=!!start&&!!end&&start<=end;const count=valid?Math.round((new Date(end+'T12:00:00')-new Date(start+'T12:00:00'))/86400000)+1:0;$('nutrition-period-error').hidden=valid;$('nutrition-period-error').textContent='Choisis une date de début antérieure ou égale à la date de fin.';const entries=Object.entries(db.days||{}).filter(([date,r])=>valid&&date>=start&&date<=end&&r.complete===true).sort((a,b)=>a[0].localeCompare(b[0])).map(([date,r])=>({date,...nutritionTotals(r.items)}));const selectedDate=$('day')?.value||today(),record=db.days?.[selectedDate],items=Array.isArray(record?.items)?record.items:[],totals=nutritionTotals(items);$('nutrition-last').textContent=fmt(totals.kcal)+' kcal';$('nutrition-last-date').textContent=displayDate(selectedDate)+(record?.complete?' · Journée complète':items.length?' · En cours':' · Aucun aliment saisi');$('nutrition-last-p').textContent='Protéines '+fmt(totals.p)+' g';$('nutrition-last-c').textContent='Glucides '+fmt(totals.c)+' g';$('nutrition-last-f').textContent='Lipides '+fmt(totals.f)+' g';$('nutrition-average').textContent=entries.length?fmt(avg(entries.map(e=>e.kcal)))+' kcal':'—';$('nutrition-complete-count').textContent=entries.length+' / '+count+' journées complètes';document.querySelectorAll('[data-nutrition-period]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.nutritionPeriod===mode)));$('nutrition-summary').innerHTML=stat('Journées complètes',entries.length+' / '+count)+[['kcal','Calories','kcal'],['p','Protéines','g'],['c','Glucides','g'],['f','Lipides','g']].map(([k,label,unit])=>stat('Moyenne '+label,entries.length?fmt(avg(entries.map(e=>e[k])))+' '+unit:'—')).join('');chart('nutrition-chart','Calories journalières',Object.entries(db.days||{}).filter(([date,r])=>valid&&date>=start&&date<=end&&Array.isArray(r.items)&&r.items.length).sort((a,b)=>a[0].localeCompare(b[0])).map(([date,r])=>({date,value:nutritionTotals(r.items).kcal,detail:r.complete?'Journée complète':'Journée en cours'})),'kcal',{start,end,valid});$('nutrition-history').innerHTML=entries.slice().reverse().map(e=>'<div class="track-entry"><span>'+displayDate(e.date)+' · '+fmt(e.kcal)+' kcal · '+fmt(e.p)+' g prot.</span></div>').join('')||'<p class="tracking-note">Aucune journée complète sur cette période.</p>';}
function displayDate(date){if(!date)return '';const [y,m,d]=date.split('-');return d+'/'+m+'/'+y;}
function renderOverview(){const db=read(),weights=Object.entries(db.weights||{}).filter(([d,v])=>/^\d{4}-\d{2}-\d{2}$/.test(d)&&Number(v)>0).sort((a,b)=>a[0].localeCompare(b[0])),lastW=weights.at(-1);$('overview-weight').textContent=lastW?fmt(lastW[1])+' kg':'— kg';$('overview-weight-date').textContent=lastW?'Le '+displayDate(lastW[0]):'Aucune pesée enregistrée';
const measures=Object.entries(db.measurements||{}).filter(([date,record])=>/^\d{4}-\d{2}-\d{2}$/.test(date)&&record&&KINDS.some(([key])=>Number(record[key])>0)).sort((a,b)=>a[0].localeCompare(b[0])),lastM=measures.at(-1);$('overview-measures').innerHTML=lastM?KINDS.filter(([key])=>Number(lastM[1][key])>0).map(([key,label])=>'<span>'+safe(label)+' <b>'+fmt(lastM[1][key])+' cm</b></span>').join(''):'<span>Aucune mensuration enregistrée</span>';$('overview-measures-date').textContent=lastM?'Relevé du '+displayDate(lastM[0]):'';
const selectedDate=$('day')?.value||today(),record=db.days?.[selectedDate],items=Array.isArray(record?.items)?record.items:[],totals=nutritionTotals(items);$('overview-calories').textContent=fmt(totals.kcal)+' kcal';$('overview-protein').textContent='Protéines '+fmt(totals.p)+' g';$('overview-carbs').textContent='Glucides '+fmt(totals.c)+' g';$('overview-fat').textContent='Lipides '+fmt(totals.f)+' g';$('overview-nutrition-date').textContent='Le '+displayDate(selectedDate)+(record?.complete?' · Journée complète':items.length?' · Journée en cours':' · Aucun aliment saisi');}

const ANALYSIS_OPTIONS=[
 {id:'weight',label:'Poids',unit:'kg',color:'#42CDA8',type:'weight'},
 ...KINDS.map(([id,label],i)=>({id,label,unit:'cm',color:['#F2B96B','#83A9F4','#F07F9B','#B993F3','#E8C28D','#69CDD5','#E7A2CA'][i],type:'measure'})),
 {id:'kcal',label:'Calories',unit:'kcal',color:'#FF9652',type:'nutrition'},
 {id:'p',label:'Protéines',unit:'g',color:'#E66ED1',type:'nutrition'},
 {id:'c',label:'Glucides',unit:'g',color:'#54B7EE',type:'nutrition'},
 {id:'f',label:'Lipides',unit:'g',color:'#A7CE69',type:'nutrition'}
];
const ANALYSIS_KEY='gp-analysis-preferences-v1';
let analysisFocus=null;
const analysisHidden=new Set();
let analysisSelectedDate=null;
let analysisPrefs=(()=>{try{const p=JSON.parse(localStorage.getItem(ANALYSIS_KEY));return {selected:Array.isArray(p?.selected)?p.selected:['weight','waist','glutes'],mode:['overview','overlay','separate','summary'].includes(p?.mode)?p.mode:'overview',window:['7','15','30','custom'].includes(p?.window)?p.window:'30'};}catch{return {selected:['weight','waist','glutes'],mode:'overview',window:'30'};}})();
function saveAnalysisPrefs(){try{localStorage.setItem(ANALYSIS_KEY,JSON.stringify(analysisPrefs));}catch{}}
function analysisEntries(option,db,range){
 const records=option.type==='weight'?db.weights||{}:option.type==='measure'?Object.fromEntries(Object.entries(db.measurements||{}).map(([d,v])=>[d,v?.[option.id]])):Object.fromEntries(Object.entries(db.days||{}).filter(([,r])=>Array.isArray(r?.items)&&r.items.length).map(([d,r])=>[d,nutritionTotals(r.items)[option.id]]));
 return Object.entries(records).filter(([date,v])=>/^\d{4}-\d{2}-\d{2}$/.test(date)&&date>=range.start&&date<=range.end&&v!=null&&Number.isFinite(Number(v))&&(option.type==='nutrition'?Number(v)>=0:Number(v)>0)).sort((a,b)=>a[0].localeCompare(b[0])).map(([date,value])=>({date,value:Number(value)}));
}
function renderAnalysis(){
 const range=period('analysis'),db=read();
 $('analysis-window').value=analysisPrefs.window;
 $('analysis-selected-count').textContent='('+analysisPrefs.selected.length+')';
 $('analysis-mode-select').value=analysisPrefs.mode;
 $('analysis-selectors').innerHTML=ANALYSIS_OPTIONS.map(o=>'<label class="analysis-choice"><input type="checkbox" data-analysis-choice="'+o.id+'" '+(analysisPrefs.selected.includes(o.id)?'checked':'')+'><span class="analysis-swatch" style="background:'+o.color+'"></span>'+safe(o.label)+'</label>').join('');
 const selected=ANALYSIS_OPTIONS.filter(o=>analysisPrefs.selected.includes(o.id)).map(o=>({...o,entries:range.valid?analysisEntries(o,db,range):[]}));
 if(!selected.length){$('analysis-results').innerHTML='<p class="tracking-note">Sélectionne un ou plusieurs indicateurs pour voir leur évolution.</p>';return;}
 if(!range.valid){$('analysis-results').innerHTML='<p class="tracking-note">Vérifie les dates de la période.</p>';return;}
 const start=range.start,end=range.end;
 const cards=selected.map(o=>{const first=o.entries[0],last=o.entries.at(-1);return '<div class="analysis-stat"><span>'+safe(o.label)+'</span><strong>'+(first&&last?diff(first.value,last.value,o.unit):'—')+'</strong><small>'+(first&&last?displayDate(first.date)+' → '+displayDate(last.date):'Pas de relevé')+'</small></div>';}).join('');
 let charts='';
 if(analysisPrefs.mode==='summary'){
 charts='';
 }else if(analysisPrefs.mode==='separate'){
 charts=selected.map(o=>'<div class="analysis-plot"><h3><span class="analysis-swatch" style="background:'+o.color+'"></span>'+safe(o.label)+'</h3><div id="analysis-chart-'+o.id+'"></div></div>').join('');
 }else{
 const available=selected.filter(o=>o.entries.length&&!analysisHidden.has(o.id));
 const days=Math.max(1,Math.round((new Date(end+'T12:00:00')-new Date(start+'T12:00:00'))/86400000)+1),w=330,h=200,left=42,right=15,top=20,bottom=35;
 const series=available.map(o=>({...o,points:o.entries.map(e=>({date:e.date,value:o.entries[0].value?100*(e.value/o.entries[0].value-1):0}))}));
 const values=series.flatMap(o=>o.points.map(p=>p.value)),lo=Math.min(0,...values),hi=Math.max(0,...values),span=Math.max(hi-lo,1),low=lo-span*.15,high=hi+span*.15;
 const x=date=>left+(w-left-right)*(new Date(date+'T12:00:00')-new Date(start+'T12:00:00'))/Math.max(1,(days-1)*86400000),y=v=>top+(h-top-bottom)*(high-v)/(high-low);
 const grid=[0,.5,1].map(t=>{const val=low+(high-low)*t;return '<line x1="'+left+'" x2="'+(w-right)+'" y1="'+y(val)+'" y2="'+y(val)+'" stroke="#b5a0b9" stroke-opacity=".3" stroke-dasharray="3 4"/><text x="1" y="'+(y(val)+4)+'" fill="#f2d7b3" font-size="10">'+fmt(val)+'%</text>';}).join('');
 const lines=series.map(o=>'<polyline fill="none" stroke="'+o.color+'" stroke-width="'+(analysisFocus===o.id?'3.2':'1.8')+'" stroke-opacity="'+(analysisFocus&&analysisFocus!==o.id?'.22':'1')+'" stroke-linejoin="round" points="'+o.points.map(p=>x(p.date)+','+y(p.value)).join(' ')+'"/>'+o.points.map(p=>'<circle cx="'+x(p.date)+'" cy="'+y(p.value)+'" r="3" fill="'+o.color+'" opacity="'+(analysisFocus&&analysisFocus!==o.id?'.22':'1')+'"><title>'+safe(o.label)+' · '+displayDate(p.date)+' · '+fmt(o.entries.find(e=>e.date===p.date).value)+' '+o.unit+' · '+fmt(p.value)+' %</title></circle>').join('')).join('');
 charts='<div class="analysis-plot"><h3>'+(analysisPrefs.mode==='overview'?'Vue d’ensemble — toutes mes courbes':'Comparaison des variations (%)')+'</h3>'+(series.length?'<svg viewBox="0 0 330 200" role="img" aria-label="Comparaison des variations relatives">'+grid+lines+'<text x="'+left+'" y="194" font-size="10" fill="#f2d7b3">'+displayDate(start).slice(0,5)+'</text><text x="'+(w-right)+'" y="194" text-anchor="end" font-size="10" fill="#f2d7b3">'+displayDate(end).slice(0,5)+'</text></svg>':'<p>Aucune donnée sur la période.</p>')+'<p class="chart-note">Chaque série commence à 0 % à son premier relevé disponible. Sélectionne une date pour lire les valeurs enregistrées.</p><div class="analysis-legend">'+selected.map(o=>'<button type="button" class="analysis-legend-item" data-analysis-focus="'+o.id+'" aria-pressed="'+(analysisFocus===o.id)+'" aria-label="Mettre en évidence '+safe(o.label)+'"><i style="background:'+o.color+'"></i>'+safe(o.label)+'</button>').join('')+'</div></div>';
 }
 if(analysisPrefs.mode==='overview'&&selected.length){
 const dates=[...new Set(selected.flatMap(o=>o.entries.map(e=>e.date)))].sort();
 const chosen=dates.includes(analysisSelectedDate)?analysisSelectedDate:dates.at(-1);
 analysisSelectedDate=chosen;
 const dateButtons='<label class="analysis-date-select-label">Date <select id="analysis-date-select" aria-label="Choisir la date du relevé">'+dates.map(d=>'<option value="'+d+'" '+(d===chosen?'selected':'')+'>'+displayDate(d)+'</option>').join('')+'</select></label>';
 const details=selected.map(o=>{const e=o.entries.find(e=>e.date===chosen);return '<div class="analysis-stat"><span><i class="analysis-swatch" style="background:'+o.color+'"></i> '+safe(o.label)+'</span><strong>'+(e?fmt(e.value)+' '+o.unit:'—')+'</strong><small>'+(e?'Relevé du '+displayDate(chosen):'Aucun relevé ce jour')+'</small></div>';}).join('');
 charts+='<details class="analysis-overview-detail"><summary>Valeurs du '+(chosen?displayDate(chosen):'—')+' · voir le détail</summary><div class="analysis-date-picker">'+dateButtons+'</div><div class="analysis-stats">'+details+'</div></details>';
 }
 $('analysis-results').innerHTML=analysisPrefs.mode==='summary'?'<h2 class="analysis-subtitle">Bilan de la période</h2><div class="analysis-stats">'+cards+'</div>':charts;
 if(analysisPrefs.mode==='separate')selected.forEach(o=>chart('analysis-chart-'+o.id,o.label,o.entries,o.unit,range,o.color));
}
$('analysis-filter-toggle').addEventListener('click',()=>{const panel=$('analysis-filter-panel');panel.hidden=!panel.hidden;$('analysis-filter-toggle').setAttribute('aria-expanded',String(!panel.hidden));});
$('analysis-filter-done').addEventListener('click',()=>{$('analysis-filter-panel').hidden=true;$('analysis-filter-toggle').setAttribute('aria-expanded','false');});
$('analysis-from').value=dayOffset(today(),-29);$('analysis-to').value=today();$('analysis-window').value=analysisPrefs.window;
$('analysis-selectors').addEventListener('change',e=>{const id=e.target.dataset.analysisChoice;if(!id)return;analysisPrefs.selected=e.target.checked?[...new Set([...analysisPrefs.selected,id])]:analysisPrefs.selected.filter(v=>v!==id);saveAnalysisPrefs();renderAnalysis();});
$('analysis-results').addEventListener('click',e=>{const b=e.target.closest('[data-analysis-focus]');if(!b)return;const id=b.dataset.analysisFocus;if(e.altKey){if(analysisHidden.has(id))analysisHidden.delete(id);else analysisHidden.add(id);}else{analysisFocus=analysisFocus===id?null:id;}renderAnalysis();});
$('analysis-results').addEventListener('change',e=>{if(e.target.id==='analysis-date-select'){analysisSelectedDate=e.target.value;renderAnalysis();const detail=$('analysis-results').querySelector('.analysis-overview-detail');if(detail)detail.open=true;}});
$('analysis-results').addEventListener('click',e=>{const b=e.target.closest('[data-analysis-date]');if(b){analysisSelectedDate=b.dataset.analysisDate;renderAnalysis();}});
$('analysis-clear').addEventListener('click',()=>{analysisPrefs.selected=[];saveAnalysisPrefs();renderAnalysis();});
$('analysis-window').addEventListener('change',()=>{analysisPrefs.window=$('analysis-window').value;saveAnalysisPrefs();renderAnalysis();});
for(const id of ['analysis-from','analysis-to'])$(id).addEventListener('change',renderAnalysis);
$('analysis-mode-select').addEventListener('change',e=>{analysisPrefs.mode=e.target.value;saveAnalysisPrefs();renderAnalysis();});
function render(){renderWeight();renderMeasure();renderNutrition();renderOverview();renderAnalysis();}
window.addEventListener('gp:nutrition-updated',()=>{renderOverview();renderNutrition();});
for(const id of ['weight','measure']){$(id+'-from').value=dayOffset(today(),-29);$(id+'-to').value=today();$(id+'-window').addEventListener('change',render);$(id+'-from').addEventListener('change',render);$(id+'-to').addEventListener('change',render);} $('measure-kind').innerHTML=KINDS.map(([key,label])=>'<option value="'+key+'">'+label+'</option>').join('');
let quickMode='weight';const quickDialog=$('quick-track-dialog');$('quick-track-measures-fields').innerHTML=KINDS.map(([key,label])=>'<label>'+label+' (cm)<input type="number" data-quick-measure="'+key+'" min="1" max="300" step="0.1" inputmode="decimal" placeholder="—"></label>').join('');document.querySelectorAll('[data-quick]').forEach(b=>b.addEventListener('click',()=>{quickMode=b.dataset.quick;$('quick-track-title').textContent=quickMode==='weight'?'Enregistrer mon poids':'Enregistrer mes mensurations';$('quick-track-date').value=today();$('quick-track-weight').hidden=quickMode!=='weight';$('quick-track-measures').hidden=quickMode!=='measure';$('quick-track-weight-value').value='';document.querySelectorAll('[data-quick-measure]').forEach(input=>input.value='');$('quick-track-error').hidden=true;quickDialog.showModal();}));$('quick-track-cancel').addEventListener('click',()=>quickDialog.close());quickDialog.addEventListener('click',e=>{if(e.target===quickDialog)quickDialog.close();});$('quick-track-form').addEventListener('submit',e=>{e.preventDefault();const date=$('quick-track-date').value,db=read();if(!date)return;const error=msg=>{$('quick-track-error').textContent=msg;$('quick-track-error').hidden=false;};if(quickMode==='weight'){const value=Number($('quick-track-weight-value').value);if(!Number.isFinite(value)||value<=0||value>500)return error('Saisis un poids valide.');db.weights=db.weights||{};db.weights[date]=value;}else{const values=[...document.querySelectorAll('[data-quick-measure]')].filter(input=>input.value.trim()!=='');if(!values.length)return error('Renseigne au moins une mensuration.');if(values.some(input=>!Number.isFinite(Number(input.value))||Number(input.value)<=0||Number(input.value)>300))return error('Vérifie les mesures saisies.');db.measurements=db.measurements||{};db.measurements[date]=db.measurements[date]||{};values.forEach(input=>db.measurements[date][input.dataset.quickMeasure]=Number(input.value));}write(db);quickDialog.close();render();});
for(const id of ['measure','nutrition']){document.querySelectorAll('[data-'+id+'-period]').forEach(b=>b.addEventListener('click',()=>{$(id+'-window').value=b.dataset[id+'Period'];id==='measure'?renderMeasure():renderNutrition();}));$(id+'-history-toggle').addEventListener('click',()=>{const panel=$(id+'-history-panel');panel.hidden=!panel.hidden;$(id+'-history-toggle').setAttribute('aria-expanded',String(!panel.hidden));});} $('nutrition-go-journal').addEventListener('click',()=>document.querySelector('[data-page="journal"]').click());
document.querySelectorAll('[data-weight-period]').forEach(b=>b.addEventListener('click',()=>{$('weight-window').value=b.dataset.weightPeriod;renderWeight();}));$('weight-history-toggle').addEventListener('click',()=>{const panel=$('weight-history-panel');panel.hidden=!panel.hidden;$('weight-history-toggle').setAttribute('aria-expanded',String(!panel.hidden));});
function openTracking(id){document.body.classList.add('inside-tracking');$('tracking-dashboard').hidden=true;$('tracking-detail').hidden=false;for(const panel of ['weight','measure','nutrition','analysis'])$('track-'+panel).hidden=panel!==id;render();window.scrollTo(0,0);}
function closeTracking(){document.body.classList.remove('inside-tracking');$('tracking-dashboard').hidden=false;$('tracking-detail').hidden=true;renderOverview();window.scrollTo(0,0);}
$('tracking-back').addEventListener('click',closeTracking);document.querySelectorAll('[data-tracking-open]').forEach(b=>b.addEventListener('click',()=>openTracking(b.dataset.trackingOpen)));
$('measure-kind').addEventListener('change',()=>{delete chartSelections['measure-chart'];renderMeasure();});$('measure-from').addEventListener('change',renderMeasure);$('measure-to').addEventListener('change',renderMeasure);$('nutrition-window').addEventListener('change',renderNutrition);$('nutrition-from').value=dayOffset(today(),-29);$('nutrition-to').value=today();$('nutrition-from').addEventListener('change',renderNutrition);$('nutrition-to').addEventListener('change',renderNutrition);
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const date=b.dataset.deleteWeight;if(date&&confirm('Supprimer cette pesée ?')){const db=read();delete db.weights[date];write(db);render();}const m=b.dataset.deleteMeasure;if(m&&confirm('Supprimer cette mesure ?')){const db=read();delete db.measurements[m][$('measure-kind').value];write(db);render();}if(b.dataset.page==='suivi'){closeTracking();render();}});
// Le mode démonstration existant est isolé des données personnelles.
$('demo-tracking-add').hidden=DEMO;
$('demo-tracking-remove').hidden=!DEMO;
$('demo-tracking-status').textContent=DEMO?'Démonstration active : 9 relevés fictifs sur 30 jours':'Aucune donnée fictive active';
$('demo-tracking-add').addEventListener('click',()=>{location.href=location.pathname+'?demo=1#suivi';});
$('demo-tracking-remove').addEventListener('click',()=>{location.href=location.pathname+'#suivi';});
window.addEventListener('storage',render);render();
})();